def llm1(self) -> float:
    if self.collected_food != "":
        return 0.0

    sum_dists = {food: self.agent_food_distance("1", food) + self.agent_food_distance("2", food) for food in self.foods_position}
    all_sums = list(sum_dists.values())
    min_sum = min(all_sums)

    non_min_sums = [s for s in all_sums if s != min_sum]
    if not non_min_sums:
        return 0.0

    avg_non_min = sum(non_min_sums) / len(non_min_sums)
    return (avg_non_min - min_sum) * 0.1

