def llm1(self) -> float:
    # Compute minimal sum of distances from both agents to any food
    min_combined_distance = min(
        self.agent_food_distance("1", food) + self.agent_food_distance("2", food)
        for food in self.foods_position.keys()
    )
    # Return negative scaled reward: higher (less negative) when closer to preferred food
    return -min_combined_distance * 0.05

